		ListBuffer<JCAnnotation> newAnnotations = new ListBuffer<JCAnnotation>();
		for (JCAnnotation ann : annotations) {
			if (jcTree.pos != ann.pos) newAnnotations.append(ann);
		}
		return newAnnotations.toList();
